<script setup>
import { computed, ref, watch } from 'vue';
import { Head, Link, router, useForm, usePage, usePoll } from '@inertiajs/vue3';
import AppLayout from '../../Layouts/AppLayout.vue';
import DeliveryMap from '../../Components/DeliveryMap.vue';
import Dialog from '../../Components/Shared/Dialog.vue';
import RupiahInput from '../../Components/Shared/RupiahInput.vue';
import { money } from '../../Support/cart.js';
defineOptions({ layout: AppLayout });
const props = defineProps({ storeName: String, origin: Object, orders: Object, run: Object, planUrl: String, bulkUrl: String, backUrl: String, mapTilesUrl: String });
const page = usePage(); const selected = ref([]); const focused = ref(null); const busy = ref(false); const confirm = ref(null);
const cash = useForm({ order_id: null, keep_change: false, cash_received: '' });
usePoll(15000, { only: ['orders', 'run'], onBefore: () => !busy.value && !cash.processing });
watch(() => [props.orders, props.run], () => { selected.value = selected.value.filter(id => props.orders.data.some(order => order.id === id && eligible(order))); });
const chosen = computed(() => props.orders.data.filter(order => selected.value.includes(order.id)));
const payable = order => order.payment_method === 'cash' || order.payment_status === 'paid';
const eligible = order => payable(order) && ['received', 'preparing', 'ready', 'out_for_delivery'].includes(order.status) && !props.run?.stops.some(stop => stop.id === order.id);
const selectAllIds = computed(() => {
    const available = props.orders.data.filter(eligible);
    const stage = available[0]?.status;
    return available.filter(order => ['ready', 'out_for_delivery'].includes(stage) ? ['ready', 'out_for_delivery'].includes(order.status) : order.status === stage).slice(0, 10).map(order => order.id);
});
const allSelected = computed(() => selectAllIds.value.length > 0 && selectAllIds.value.every(id => selected.value.includes(id)));
const toggleAll = () => { selected.value = allSelected.value ? [] : [...selectAllIds.value]; };

const canPrepare = computed(() => chosen.value.length > 0 && chosen.value.every(order => order.status === 'received' && payable(order)));
const canReady = computed(() => chosen.value.length > 0 && chosen.value.every(order => order.status === 'preparing' && payable(order)));
const canPlan = computed(() => chosen.value.length > 0 && chosen.value.length <= 10 && chosen.value.every(order => ['ready', 'out_for_delivery'].includes(order.status) && payable(order)));
const next = computed(() => props.run?.stops.find(stop => stop.status !== 'completed'));
const shownStops = computed(() => props.run?.stops || chosen.value);
const completed = computed(() => props.run?.stops.filter(stop => stop.status === 'completed').length || 0);
const navigate = stop => `https://www.google.com/maps/dir/?api=1&destination=${encodeURIComponent(`${stop.location.latitude},${stop.location.longitude}`)}&travelmode=driving`;
const perform = (url, data = {}) => { if (busy.value) return; busy.value = true; router.post(url, data, { preserveScroll: true, onSuccess: () => { selected.value = []; confirm.value = null; }, onFinish: () => { busy.value = false; } }); };
const ask = (type, url, data = {}) => { confirm.value = { type, url, data }; };
const finish = () => { cash.order_id = next.value.id; cash.post(props.run.completeUrl, { preserveScroll: true, onSuccess: () => { cash.reset(); confirm.value = null; } }); };
const distance = meters => meters < 1000 ? `${meters} m` : `${(meters / 1000).toFixed(1)} km`;
</script>
<template>
<Head title="Delivery queue"/>
<Link :href="backUrl" class="text-sm text-stone-500 underline">← My store</Link>
<div class="mt-5 flex flex-wrap items-end justify-between gap-4"><div><p class="text-xs uppercase tracking-widest text-stone-500">{{ storeName }} · Delivery workspace</p><h1 class="mt-3 text-3xl font-semibold">One trip. Clear next steps.</h1><p class="mt-3 text-sm leading-6 text-stone-500">Prepare together, then follow your delivery stops in order.</p></div></div>
<p v-if="page.props.status" role="status" class="mt-5 rounded-2xl bg-green-50 p-4 text-sm text-green-800">{{ page.props.status }}</p>
<div v-if="Object.keys(page.props.errors).length" role="alert" class="mt-5 rounded-2xl bg-red-50 p-4 text-sm text-red-700"><p v-for="(message,key) in page.props.errors" :key="key">{{ message }}</p></div>
<section v-if="run" class="mt-8"><div class="mb-5 flex flex-wrap items-center justify-between gap-4"><div><h2 class="text-xl font-semibold">{{ run.status === 'active' ? 'On the road' : 'Your delivery plan' }}</h2><p class="mt-2 text-sm text-stone-500">{{ completed }} / {{ run.stops.length }} delivered · {{ distance(run.distance_m) }} planned from store</p></div><div v-if="run.status === 'planned'" class="flex gap-3"><button :disabled="busy" class="rounded-full border border-stone-300 px-4 py-3 text-sm" @click="ask('Clear this route?', run.clearUrl)">Clear plan</button><button :disabled="busy" class="rounded-full bg-[#504941] px-5 py-3 text-sm font-medium text-white" @click="ask('Start all deliveries?', run.startUrl)">Start delivery trip →</button></div></div>
<div class="grid items-start gap-6 lg:grid-cols-[1.15fr_1fr]"><div class="lg:sticky lg:top-28"><DeliveryMap :origin="run.origin" :stops="shownStops" :tiles-url="mapTilesUrl" :selected="focused || next?.id" @select="focused = $event"/><p class="mt-3 text-xs leading-5 text-stone-500">Stop order uses road distances, choosing the nearest remaining destination each time. Estimates exclude traffic and the return trip. Routes by <a href="https://project-osrm.org/" target="_blank" rel="noreferrer noopener" class="underline">OSRM</a> · © OpenStreetMap contributors.</p></div>
<ol class="space-y-3"><li v-for="(stop,index) in run.stops" :key="stop.id" class="rounded-2xl border bg-white p-5 transition-colors" :class="stop.id === (focused || next?.id) ? 'border-blue-300 ring-2 ring-blue-100' : 'border-stone-200'"><button class="flex w-full items-start gap-3 text-left" @click="focused = stop.id"><span class="flex size-9 shrink-0 items-center justify-center rounded-full text-sm font-semibold" :class="stop.status === 'completed' ? 'bg-green-100 text-green-800' : 'bg-[#504941] text-white'">{{ stop.status === 'completed' ? '✓' : index + 1 }}</span><span class="min-w-0 flex-1"><span class="block font-semibold">{{ stop.customer_name }}</span><span class="mt-1 block text-xs text-stone-500">{{ stop.reference }} · {{ distance(stop.distance_m) }} from previous stop</span></span><span v-if="stop.id === next?.id" class="rounded-full bg-blue-50 px-2 py-1 text-xs text-blue-800">Next stop</span></button><p v-if="stop.location.delivery_service_name" class="mt-3 text-sm font-semibold">{{ stop.location.delivery_service_name }} delivery</p><p class="mt-4 text-sm leading-6">{{ stop.location.address_line }}</p><a :href="`tel:${stop.phone}`" class="mt-2 inline-block text-sm text-stone-500 underline">{{ stop.phone }}</a><p v-for="(item,i) in stop.items" :key="i" class="mt-3 text-sm">{{ item.quantity }} × {{ item.name }}<span class="mt-1 block text-xs text-stone-500">{{ item.choices.map(choice => `${choice.group}: ${choice.name}`).join(' · ') }}</span></p><p class="mt-4 text-sm font-medium" :class="stop.payment_status === 'paid' ? 'text-green-800' : 'text-amber-800'">{{ stop.payment_status === 'paid' ? 'Paid' : 'Collect cash' }} · {{ money(stop.total) }}</p><div v-if="stop.status !== 'completed'" class="mt-4 flex flex-wrap gap-3"><a :href="navigate(stop)" target="_blank" rel="noreferrer noopener" class="rounded-full border border-stone-300 px-4 py-3 text-sm">Navigate ↗</a><button v-if="run.status === 'active' && stop.id === next?.id" class="rounded-full bg-[#504941] px-4 py-3 text-sm text-white" @click="confirm = { type: 'Complete this delivery?', complete: true }; cash.clearErrors()">Mark delivered</button></div></li></ol></div></section>
<section v-if="!run" class="mt-10"><div class="flex flex-wrap items-center justify-between gap-4"><div><h2 class="text-xl font-semibold">Orders to prepare & deliver</h2><p class="mt-2 text-sm text-stone-500">Select up to 10 orders at the same stage. {{ orders.total }} pending deliveries.</p></div><span class="rounded-full bg-white px-4 py-2 text-sm">{{ selected.length }} selected</span></div><div v-if="selected.length" class="mt-5 flex flex-wrap gap-3 rounded-2xl border border-stone-200 bg-white p-4"><button v-if="canPrepare" :disabled="busy" class="rounded-full bg-[#504941] px-4 py-3 text-sm text-white" @click="ask('Prepare selected orders together?', bulkUrl, { orders: selected, stage: 'preparing' })">Prepare together</button><button v-if="canReady" :disabled="busy" class="rounded-full bg-[#504941] px-4 py-3 text-sm text-white" @click="ask('Mark selected orders ready?', bulkUrl, { orders: selected, stage: 'ready' })">Mark all ready</button><button v-if="!run && canPlan" :disabled="busy" class="rounded-full bg-[#504941] px-4 py-3 text-sm text-white" @click="perform(planUrl, { orders: selected })">{{ busy ? 'Calculating road distances…' : 'Plan delivery route →' }}</button><button class="px-3 py-2 text-sm underline" @click="selected = []">Clear selection</button><p v-if="!canPrepare && !canReady && !canPlan" class="w-full text-sm text-stone-500">Choose paid or cash orders at the same preparation stage.</p></div>
<div class="mt-5 overflow-x-auto rounded-2xl border border-stone-200 bg-white"><table class="w-full min-w-[640px] text-left text-sm"><thead class="bg-stone-50 text-xs text-stone-500"><tr><th class="p-4"><input type="checkbox" :checked="allSelected" :indeterminate="selected.length > 0 && !allSelected" :disabled="!selectAllIds.length" aria-label="Select up to 10 available orders at the same stage" class="size-4 accent-stone-700" @change="toggleAll"/></th><th class="p-4">Customer / destination</th><th class="p-4">Progress</th><th class="p-4">Payment</th><th class="p-4">Map</th></tr></thead><tbody class="divide-y divide-stone-100"><tr v-for="order in orders.data" :key="order.id"><td class="p-4"><span v-if="run?.stops.some(stop => stop.id === order.id)" class="text-xs font-medium text-stone-500">In current trip</span><input v-else v-model="selected" type="checkbox" :value="order.id" :disabled="!eligible(order) || (!selected.includes(order.id) && selected.length >= 10)" :aria-label="`Select ${order.reference}`" class="size-4 accent-stone-700"/></td><td class="p-4"><p class="font-medium">{{ order.customer_name }}</p><p v-if="order.location.delivery_service_name" class="mt-1 text-xs font-semibold">{{ order.location.delivery_service_name }} delivery</p><p class="mt-1 text-xs text-stone-500">{{ order.reference }}</p><p class="mt-2 max-w-sm text-xs leading-5 text-stone-500">{{ order.location.address_line }}</p></td><td class="p-4"><span class="rounded-full bg-stone-100 px-3 py-1.5 text-xs capitalize">{{ order.status.replaceAll('_', ' ') }}</span></td><td class="p-4"><p>{{ money(order.total) }}</p><p class="mt-1 text-xs" :class="payable(order) ? 'text-green-800' : 'text-amber-800'">{{ order.payment_status === 'paid' ? 'Paid' : order.payment_method === 'cash' ? 'Cash on delivery' : 'Awaiting payment' }}</p></td><td class="p-4"><a v-if="['ready', 'out_for_delivery'].includes(order.status)" :href="navigate(order)" target="_blank" rel="noreferrer noopener" class="underline">Navigate ↗</a></td></tr><tr v-if="!orders.data.length"><td colspan="5" class="p-10 text-center text-stone-500">All caught up. No pending deliveries.</td></tr></tbody></table></div><nav class="mt-4 flex justify-between text-sm"><Link v-if="orders.prev_page_url" :href="orders.prev_page_url" class="underline">← Previous</Link><span v-else/><Link v-if="orders.next_page_url" :href="orders.next_page_url" class="underline">Next →</Link></nav></section>
<Dialog :open="Boolean(confirm)" :title="confirm?.type" :busy="busy || cash.processing" @close="confirm = null"><template v-if="confirm?.complete && next"><p class="text-sm leading-6">Hand over {{ next.reference }} to {{ next.customer_name }} before confirming.</p><div v-if="next.payment_status !== 'paid'" class="mt-5"><RupiahInput v-model="cash.cash_received" name="delivery-cash" label="Cash received" :error="cash.errors.cash_received"/><label class="mt-3 flex items-center gap-2 text-sm"><input v-model="cash.keep_change" type="checkbox">Customer leaves the change</label><span class="mt-2 block text-xs text-stone-500">Amount due {{ money(next.total) }}<span v-if="Number(cash.cash_received) >= next.total"> · Change {{ money(cash.keep_change ? 0 : Number(cash.cash_received) - next.total) }}</span></span></div><p v-else class="mt-3 text-sm text-green-800">Already paid. Do not charge again.</p><p v-for="(message,key) in cash.errors" :key="key" role="alert" class="mt-3 text-sm text-red-700">{{ message }}</p><button :disabled="cash.processing" class="mt-6 w-full rounded-full bg-[#504941] px-5 py-3 text-sm text-white" @click="finish">{{ cash.processing ? 'Saving…' : 'Confirm delivery' }}</button></template><template v-else><p class="text-sm leading-6">{{ confirm?.type === 'Clear this route?' ? 'Clear this planned route so you can choose the stops again. Orders keep their current progress.' : 'The selected orders will update together. Customers will see their own order progress.' }}</p><button :disabled="busy" class="mt-6 w-full rounded-full bg-[#504941] px-5 py-3 text-sm text-white" @click="perform(confirm.url, confirm.data)">{{ busy ? 'Updating…' : 'Confirm' }}</button></template></Dialog>
</template>
